<?php
declare(strict_types=1);
$isHttps=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&$_SERVER['HTTPS']!=='off';ini_set('session.use_strict_mode','1');session_name('coaching_tool_session');session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']);session_start();header('Cache-Control: no-store, private');require_once dirname(__DIR__).'/app/bootstrap.php';require_once dirname(__DIR__).'/app/theme.php';require_once dirname(__DIR__).'/app/document_storage.php';
function portalH(string|int|null $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$user=$_SESSION['user']??null;if(!is_array($user)||($user['role']??'')!=='client'||!isset($user['client_id'],$user['id'])){header('Location: ./');exit;}
$db=coachingDatabase();$clientId=(int)$user['client_id'];$portalId=(int)$user['id'];$activeCheck=$db->prepare('SELECT aktiv FROM coaching_portal_zugaenge WHERE id=:id AND klient_id=:client');$activeCheck->execute(['id'=>$portalId,'client'=>$clientId]);if((int)$activeCheck->fetchColumn()!==1){unset($_SESSION['user']);session_regenerate_id(true);header('Location: ./');exit;}$prefQuery=$db->prepare('SELECT aufgaben_erinnerungen_aktiv,aufgaben_erinnerung_rhythmus,aufgaben_ruhe_von,aufgaben_ruhe_bis FROM coaching_portal_zugaenge WHERE id=:id AND klient_id=:client');$prefQuery->execute(['id'=>$portalId,'client'=>$clientId]);$reminderPrefs=$prefQuery->fetch(PDO::FETCH_ASSOC)?:['aufgaben_erinnerungen_aktiv'=>0,'aufgaben_erinnerung_rhythmus'=>'taeglich','aufgaben_ruhe_von'=>'21:00:00','aufgaben_ruhe_bis'=>'08:00:00'];$token=$_SESSION['csrf_token']??'';if(!is_string($token)||strlen($token)!==64){$token=bin2hex(random_bytes(32));$_SESSION['csrf_token']=$token;}
$q=$db->prepare('SELECT id,vorname,nachname,benutzer_id FROM klienten WHERE id=:id');$q->execute(['id'=>$clientId]);$client=$q->fetch(PDO::FETCH_ASSOC);if(!$client){http_response_code(404);exit('Klient nicht gefunden.');}$coachId=(int)$client['benutzer_id'];
$orderQuery=$db->prepare("SELECT id,titel FROM coaching_auftraege WHERE klient_id=:client AND coach_benutzer_id=:coach AND status='aktiv' ORDER BY id DESC LIMIT 1");$orderQuery->execute(['client'=>$clientId,'coach'=>$coachId]);$activeOrder=$orderQuery->fetch(PDO::FETCH_ASSOC)?:null;$activeOrderId=(int)($activeOrder['id']??0);
$releasedQuery=$db->prepare("SELECT id,titel,abgeschlossen_am FROM coaching_auftraege WHERE klient_id=:client AND coach_benutzer_id=:coach AND status='abgeschlossen' AND archiv_freigegeben=1 ORDER BY abgeschlossen_am DESC,id DESC");$releasedQuery->execute(['client'=>$clientId,'coach'=>$coachId]);$releasedArchives=$releasedQuery->fetchAll(PDO::FETCH_ASSOC);
$notice=isset($_GET['message_sent'])?'Nachricht wurde gesendet.':'';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($token,(string)($_POST['csrf_token']??''))){http_response_code(400);exit('Ungültige Anfrage.');}$action=(string)($_POST['action']??'');
if($action==='password'){$old=(string)($_POST['aktuelles_passwort']??'');$new=(string)($_POST['neues_passwort']??'');$q=$db->prepare('SELECT passwort_hash FROM coaching_portal_zugaenge WHERE id=:id AND klient_id=:client AND aktiv=1');$q->execute(['id'=>$portalId,'client'=>$clientId]);$hash=$q->fetchColumn();if(!is_string($hash)||!password_verify($old,$hash))$error='Das aktuelle Passwort ist nicht korrekt.';elseif(strlen($new)<8||strlen($new)>4096)$error='Das neue Passwort muss mindestens 8 Zeichen haben.';else{$q=$db->prepare('UPDATE coaching_portal_zugaenge SET passwort_hash=:hash WHERE id=:id AND klient_id=:client');$q->execute(['hash'=>password_hash($new,PASSWORD_DEFAULT),'id'=>$portalId,'client'=>$clientId]);$notice='Passwort geändert.';}}if($action==='reminder-settings'){
 $enabled=isset($_POST['erinnerungen_aktiv'])?1:0;
 $frequency=(string)($_POST['erinnerung_rhythmus']??'taeglich');
 $quietFrom=(string)($_POST['ruhe_von']??'21:00');$quietTo=(string)($_POST['ruhe_bis']??'08:00');
 if(!in_array($frequency,['taeglich','woechentlich'],true)||!preg_match('/^(?:[01]\\d|2[0-3]):[0-5]\\d$/',$quietFrom)||!preg_match('/^(?:[01]\\d|2[0-3]):[0-5]\\d$/',$quietTo))$error='Bitte prüfe Rhythmus und Ruhezeit.';
 else{$q=$db->prepare('UPDATE coaching_portal_zugaenge SET aufgaben_erinnerungen_aktiv=:enabled,aufgaben_erinnerung_rhythmus=:frequency,aufgaben_ruhe_von=:quiet_from,aufgaben_ruhe_bis=:quiet_to WHERE id=:id AND klient_id=:client AND aktiv=1');$q->execute(['enabled'=>$enabled,'frequency'=>$frequency,'quiet_from'=>$quietFrom.':00','quiet_to'=>$quietTo.':00','id'=>$portalId,'client'=>$clientId]);$notice=$enabled?'Aufgabenerinnerungen gespeichert.':'Aufgabenerinnerungen ausgeschaltet.';}
}
if($action==='task'){
 $id=(int)($_POST['task_id']??0);$status=(string)($_POST['status']??'');
 if($activeOrderId>0&&in_array($status,['offen','in_bearbeitung','erledigt'],true)){
  try{
   $db->beginTransaction();
   $q=$db->prepare('SELECT id,titel,status FROM coaching_aufgaben WHERE id=:id AND klient_id=:client AND coach_benutzer_id=:coach AND auftrag_id=:order AND klient_sichtbar=1 FOR UPDATE');
   $q->execute(['id'=>$id,'client'=>$clientId,'coach'=>$coachId,'order'=>$activeOrderId]);$task=$q->fetch(PDO::FETCH_ASSOC);
   if(!$task)throw new RuntimeException('Aufgabe nicht gefunden.');
   if($task['status']!==$status){
    $q=$db->prepare('UPDATE coaching_aufgaben SET status=:status WHERE id=:id AND klient_id=:client AND coach_benutzer_id=:coach AND auftrag_id=:order AND klient_sichtbar=1');
    $q->execute(['status'=>$status,'id'=>$id,'client'=>$clientId,'coach'=>$coachId,'order'=>$activeOrderId]);
    $q=$db->prepare("INSERT INTO coaching_aktivitaeten (coach_benutzer_id,klient_id,auftrag_id,ereignistyp,referenz_id,objekt_titel,status_vorher,status_nachher) VALUES (:coach,:client,:order,'aufgabenstatus',:ref,:title,:before,:after)");
    $q->execute(['coach'=>$coachId,'client'=>$clientId,'order'=>$activeOrderId,'ref'=>$id,'title'=>$task['titel'],'before'=>$task['status'],'after'=>$status]);
   }
   $db->commit();$notice='Aufgabe aktualisiert.';
  }catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Coachee task status update failed: '.$e->getMessage());$error='Aufgabenstatus konnte nicht gespeichert werden.';}
 }
}
if($action==='message'&&$activeOrderId>0){$body=trim((string)($_POST['inhalt']??''));$upload=$_FILES['datei']??null;$hasFile=is_array($upload)&&(int)($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE;if(strlen($body)>10000)$error='Nachrichten dürfen höchstens 10.000 Zeichen enthalten.';elseif($body===''&&!$hasFile)$error='Bitte schreibe eine Nachricht oder füge eine Datei an.';else{$stored=null;try{if($hasFile)$stored=coachingStoreDocumentUpload($upload,['application/pdf','image/jpeg','image/png']);$db->beginTransaction();$s=$db->prepare('INSERT INTO coaching_nachrichten (klient_id,coach_benutzer_id,auftrag_id,autor_rolle,inhalt) VALUES (:client,:coach,:order,\'client\',:body)');$s->execute(['client'=>$clientId,'coach'=>$coachId,'order'=>$activeOrderId,'body'=>$body]);$messageId=(int)$db->lastInsertId();if($stored){$f=$db->prepare('INSERT INTO coaching_nachrichten_dateien (nachricht_id,klient_id,coach_benutzer_id,speicher_schluessel,originalname,mime_typ,groesse_bytes) VALUES (:message,:client,:coach,:key,:name,:mime,:size)');$f->execute(['message'=>$messageId,'client'=>$clientId,'coach'=>$coachId,'key'=>$stored['key'],'name'=>$stored['name'],'mime'=>$stored['mime'],'size'=>$stored['size']]);}$activity=$db->prepare("INSERT INTO coaching_aktivitaeten (coach_benutzer_id,klient_id,auftrag_id,ereignistyp,referenz_id) VALUES (:coach,:client,:order,'coachee_nachricht',:ref)");$activity->execute(['coach'=>$coachId,'client'=>$clientId,'order'=>$activeOrderId,'ref'=>$messageId]);$db->commit();header('Location: portal.php?message_sent=1#messages');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($stored&&is_file($stored['path']))@unlink($stored['path']);error_log('Coachee message save failed: '.$e->getMessage());$error=$e instanceof InvalidArgumentException?$e->getMessage():'Nachricht konnte nicht gesendet werden. Bitte später erneut versuchen.';}}}
}
$themeCss=coachingThemeCss($db,$coachId);
$q=$db->prepare('SELECT beginn,dauer_minuten,format,status FROM termine WHERE klient_id=:client AND auftrag_id=:order ORDER BY beginn DESC LIMIT 50');$q->execute(['client'=>$clientId,'order'=>$activeOrderId]);$appointments=$q->fetchAll(PDO::FETCH_ASSOC);$unreadCoachMessages=0;if($activeOrderId>0){$uq=$db->prepare("SELECT COUNT(*) FROM coaching_nachrichten WHERE klient_id=:client AND coach_benutzer_id=:coach AND auftrag_id=:order AND autor_rolle='coach' AND coachee_gelesen_am IS NULL");$uq->execute(['client'=>$clientId,'coach'=>$coachId,'order'=>$activeOrderId]);$unreadCoachMessages=(int)$uq->fetchColumn();if($unreadCoachMessages>0){$markRead=$db->prepare("UPDATE coaching_nachrichten SET coachee_gelesen_am=NOW() WHERE klient_id=:client AND coach_benutzer_id=:coach AND auftrag_id=:order AND autor_rolle='coach' AND coachee_gelesen_am IS NULL");$markRead->execute(['client'=>$clientId,'coach'=>$coachId,'order'=>$activeOrderId]);}}$mq=$db->prepare('SELECT id,autor_rolle,inhalt,erstellt_am,coachee_gelesen_am FROM coaching_nachrichten WHERE klient_id=:client AND coach_benutzer_id=:coach AND auftrag_id=:order ORDER BY id DESC LIMIT 100');$mq->execute(['client'=>$clientId,'coach'=>$coachId,'order'=>$activeOrderId]);$messages=array_reverse($mq->fetchAll(PDO::FETCH_ASSOC));$messageFiles=[];$fq=$db->prepare('SELECT f.id,f.nachricht_id,f.originalname FROM coaching_nachrichten_dateien f INNER JOIN coaching_nachrichten n ON n.id=f.nachricht_id WHERE f.klient_id=:client AND f.coach_benutzer_id=:coach AND n.auftrag_id=:order ORDER BY f.id');$fq->execute(['client'=>$clientId,'coach'=>$coachId,'order'=>$activeOrderId]);foreach($fq->fetchAll(PDO::FETCH_ASSOC) as $f)$messageFiles[(int)$f['nachricht_id']][]=$f;
$q=$db->prepare('SELECT titel,beschreibung,erfolgskriterium,zieltermin,status FROM coaching_ziele WHERE klient_id=:client AND coach_benutzer_id=:coach AND auftrag_id=:order ORDER BY geaendert_am DESC LIMIT 100');$q->execute(['client'=>$clientId,'coach'=>$coachId,'order'=>$activeOrderId]);$goals=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$db->prepare('SELECT id,titel,beschreibung,faellig_am,status FROM coaching_aufgaben WHERE klient_id=:client AND coach_benutzer_id=:coach AND auftrag_id=:order AND klient_sichtbar=1 ORDER BY (status=\'erledigt\'),faellig_am IS NULL,faellig_am LIMIT 100');$q->execute(['client'=>$clientId,'coach'=>$coachId,'order'=>$activeOrderId]);$tasks=$q->fetchAll(PDO::FETCH_ASSOC);
$q=$db->prepare("SELECT id,titel,vorlage_version,status,zugewiesen_am FROM coaching_klientendokumente WHERE klient_id=:client AND auftrag_id=:order AND status IN ('zugewiesen','ausgegeben','zurueckgekommen') ORDER BY zugewiesen_am DESC LIMIT 100");$q->execute(['client'=>$clientId,'order'=>$activeOrderId]);$docs=$q->fetchAll(PDO::FETCH_ASSOC);$files=[];$fq=$db->prepare('SELECT f.id,f.klientendokument_id,f.version,f.originalname FROM coaching_dokumentdateien f INNER JOIN coaching_klientendokumente d ON d.id=f.klientendokument_id WHERE d.klient_id=:client AND d.auftrag_id=:order AND d.status IN (\'zugewiesen\',\'ausgegeben\',\'zurueckgekommen\') ORDER BY f.hochgeladen_am DESC');$fq->execute(['client'=>$clientId,'order'=>$activeOrderId]);foreach($fq->fetchAll(PDO::FETCH_ASSOC) as $f)$files[(int)$f['klientendokument_id']][]=$f;
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mein Coaching</title><link rel="stylesheet" href="assets/layout.css"><style>body.portal{display:block;background:#f5f7f5}.portal-wrap{max-width:1100px;margin:auto;padding:24px 18px 60px}.portal-head,.card{background:white;border:1px solid #e4ebe6;border-radius:15px;padding:20px;margin:15px 0}.portal-head{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.portal-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.row{border-top:1px solid #edf1ee;padding:12px 0}.muted{color:#718078;font-size:13px}.form{display:flex;gap:8px;flex-wrap:wrap}.form input,.form select{padding:9px;border:1px solid #dce5df;border-radius:8px}.button{background:#245c50;color:white;border:0;border-radius:8px;padding:9px 12px}.notice{background:#edf5ef;padding:12px;border-radius:9px}.badge-new{display:inline-block;background:#dcefe5;color:#195b45;border-radius:999px;padding:2px 9px;font-size:12px;font-weight:700}.error{background:#fff3f1;padding:12px}@media(max-width:700px){.portal-grid{grid-template-columns:1fr}}.message-form{display:grid;grid-template-columns:minmax(0,1fr);gap:10px;margin-top:14px}.message-form>label{display:block;font-weight:600}.message-form textarea{display:block;width:100%;min-height:120px;box-sizing:border-box;padding:12px;border:1px solid #dce5df;border-radius:9px;font:inherit;resize:vertical}.message-form input[type=file]{display:block;width:100%;max-width:100%;box-sizing:border-box;margin-top:7px;padding:10px;border:1px solid #dce5df;border-radius:9px;background:#fff;font:inherit}.message-form button{justify-self:start}</style><style><?= $themeCss ?></style></head><body class="portal"><main class="portal-wrap"><header class="portal-head"><div><strong>Mein Coaching</strong><div class="muted"><?=portalH($client['vorname'].' '.$client['nachname'])?></div></div><form method="post" action="./"><input type="hidden" name="action" value="logout"><input type="hidden" name="csrf_token" value="<?=portalH($token)?>"><button class="button">Abmelden</button></form></header><?php if($notice):?><p class="notice"><?=portalH($notice)?></p><?php endif;?><?php if($error):?><p class="error"><?=portalH($error)?></p><?php endif;?><?php if($unreadCoachMessages>0):?><p class="notice" role="status"><strong>Neue Nachricht von deinem Coach (<?= (int)$unreadCoachMessages ?>).</strong> <a href="#messages">Zum Nachrichtenverlauf</a></p><?php endif;?>
<div class="portal-grid"><?php if($releasedArchives):?><section class="card"><h2>Freigegebene Archive</h2><?php foreach($releasedArchives as $archive):?><div class="row"><strong><?=portalH($archive['titel'])?></strong> · abgeschlossen <?=portalH($archive['abgeschlossen_am']?date('d.m.Y',strtotime($archive['abgeschlossen_am'])):'')?><div><a href="portal-archive.php?id=<?=(int)$archive['id']?>">Archiv öffnen</a></div></div><?php endforeach;?></section><?php endif;?><section class="card"><h2>Aktueller Coaching-Auftrag</h2><p><?= $activeOrder?portalH($activeOrder['titel']):'Derzeit ist kein aktiver Auftrag hinterlegt.' ?></p></section><section class="card"><h2>Termine</h2><?php if(!$appointments):?><p class="muted">Noch keine Termine.</p><?php else:foreach($appointments as $a):?><div class="row"><strong><?=portalH(date('d.m.Y · H:i',strtotime($a['beginn'])))?></strong><div class="muted"><?=portalH($a['format'].' · '.$a['dauer_minuten'].' Minuten · '.$a['status'])?></div></div><?php endforeach;endif;?></section>
<section class="card" id="messages"><h2>Nachrichtenverlauf</h2><?php if(!$messages):?><p class="muted">Noch keine Nachrichten. Schreibe deinem Coach über das Formular.</p><?php else:foreach($messages as $m):?><div class="row"><strong><?= $m['autor_rolle']==='client'?'Du':'Coach' ?> · <?=portalH(date('d.m.Y H:i',strtotime($m['erstellt_am'])))?></strong><?php if($m['autor_rolle']==='coach'&&$m['coachee_gelesen_am']===null):?> <span class="badge-new">Neu</span><?php endif;?><?php if($m['inhalt']!==''):?><div style="white-space:pre-wrap"><?=portalH($m['inhalt'])?></div><?php endif;?><?php foreach($messageFiles[(int)$m['id']]??[] as $f):?><div class="muted"><a href="message-download.php?id=<?=(int)$f['id']?>"><?=portalH($f['originalname'])?> herunterladen</a></div><?php endforeach;?></div><?php endforeach;endif;?><?php if($activeOrder):?><form method="post" enctype="multipart/form-data" class="message-form"><input type="hidden" name="csrf_token" value="<?=portalH($token)?>"><input type="hidden" name="action" value="message"><label for="portal-message-body">Nachricht an deinen Coach</label><textarea id="portal-message-body" name="inhalt" maxlength="10000" rows="4" placeholder="Nachricht schreiben …"></textarea><label>Anhang (PDF, JPG oder PNG; bis 15 MB)<input type="file" name="datei" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png"></label><button class="button">Nachricht senden</button></form><?php endif;?></section>
<section class="card"><h2>Meine Ziele</h2><?php if(!$goals):?><p class="muted">Noch keine Ziele freigegeben.</p><?php else:foreach($goals as $g):?><div class="row"><strong><?=portalH($g['titel'])?> · <?=portalH($g['status'])?></strong><div class="muted"><?=portalH($g['beschreibung']??'')?><?= $g['zieltermin']?' · Zieltermin '.portalH(date('d.m.Y',strtotime($g['zieltermin']))):''?></div></div><?php endforeach;endif;?></section>
<section class="card"><h2>Aufgaben und Übungen</h2><?php if(!$tasks):?><p class="muted">Keine offenen Aufgaben.</p><?php else:foreach($tasks as $t):?><div class="row"><strong><?=portalH($t['titel'])?></strong><div class="muted"><?=portalH($t['beschreibung']??'')?><?= $t['faellig_am']?' · Fällig '.portalH(date('d.m.Y',strtotime($t['faellig_am']))):''?></div><form class="form" method="post"><input type="hidden" name="csrf_token" value="<?=portalH($token)?>"><input type="hidden" name="action" value="task"><input type="hidden" name="task_id" value="<?=(int)$t['id']?>"><select name="status"><option value="offen" <?=$t['status']==='offen'?'selected':''?>>Offen</option><option value="in_bearbeitung" <?=$t['status']==='in_bearbeitung'?'selected':''?>>In Bearbeitung</option><option value="erledigt" <?=$t['status']==='erledigt'?'selected':''?>>Erledigt</option></select><button class="button">Speichern</button></form></div><?php endforeach;endif;?></section>
<section class="card"><h2>Dokumente</h2><?php if(!$docs):?><p class="muted">Keine Dokumente bereitgestellt.</p><?php else:foreach($docs as $d):?><div class="row"><strong><?=portalH($d['titel'])?> · <?=portalH($d['status'])?></strong><div class="muted"><a href="document-download.php?type=assigned-template&amp;id=<?=(int)$d['id']?>">Dokument öffnen</a></div><?php foreach($files[(int)$d['id']]??[] as $f):?><div class="muted">Unterschriebene Fassung v<?=(int)$f['version']?> · <?=portalH($f['originalname'])?> · <a href="document-download.php?type=return&amp;id=<?=(int)$f['id']?>">Öffnen</a></div><?php endforeach;?></div><?php endforeach;endif;?></section>
<section class="card"><h2>Aufgabenerinnerungen</h2><p class="muted">Du entscheidest, ob du per E-Mail an fällige und überfällige Aufgaben erinnert werden möchtest. Nachrichten enthalten keine Aufgabentitel oder Coaching-Inhalte.</p><form method="post" class="form"><input type="hidden" name="csrf_token" value="<?=portalH($token)?>"><input type="hidden" name="action" value="reminder-settings"><label><input type="checkbox" name="erinnerungen_aktiv" value="1" <?=$reminderPrefs['aufgaben_erinnerungen_aktiv']?'checked':''?>> E-Mail-Erinnerungen einschalten</label><label>Häufigkeit<select name="erinnerung_rhythmus"><option value="taeglich" <?=$reminderPrefs['aufgaben_erinnerung_rhythmus']==='taeglich'?'selected':''?>>Täglich</option><option value="woechentlich" <?=$reminderPrefs['aufgaben_erinnerung_rhythmus']==='woechentlich'?'selected':''?>>Wöchentlich</option></select></label><div class="grid"><label>Ruhezeit von<input type="time" name="ruhe_von" value="<?=portalH(substr((string)$reminderPrefs['aufgaben_ruhe_von'],0,5))?>" required></label><label>Ruhezeit bis<input type="time" name="ruhe_bis" value="<?=portalH(substr((string)$reminderPrefs['aufgaben_ruhe_bis'],0,5))?>" required></label></div><p class="muted">Außerhalb der Ruhezeit wird höchstens eine Erinnerung pro gewähltem Zeitraum versendet. Die Funktion startet, sobald dein Coach den E-Mail-Versand eingerichtet hat.</p><button class="button">Einstellungen speichern</button></form></section><section class="card"><h2>Passwort ändern</h2><form method="post" class="form"><input type="hidden" name="csrf_token" value="<?=portalH($token)?>"><input type="hidden" name="action" value="password"><input type="password" name="aktuelles_passwort" placeholder="Aktuelles Passwort" required><input type="password" name="neues_passwort" placeholder="Neues Passwort (mind. 8 Zeichen)" minlength="8" required><button class="button">Ändern</button></form></section></div></main></body></html>